257	/// Load a single config file and parse it into BivvyConfig.
258	///
259	/// # Errors
260	///
261	/// Returns `ConfigNotFound` if the file doesn't exist.
262	/// Returns `ConfigParseError` if the YAML is invalid.
263	pub fn load_config_file(path: &Path) -> Result<BivvyConfig> {
264	    let content = fs::read_to_string(path).map_err(|e| {
265	        if e.kind() == std::io::ErrorKind::NotFound {
266	            BivvyError::ConfigNotFound {
267	                path: path.to_path_buf(),
268	            }
269	        } else {
270	            BivvyError::Io(e)
271	        }
272	    })?;
273	
274	    parse_config(&content, path)
275	}
