349	/// Parse a single workflow file into a [`WorkflowFile`], auto-detecting
350	/// new vs. legacy format.
351	///
352	/// New format: file has a top-level `workflow:` mapping. The whole file
353	/// is parsed as `WorkflowFile`.
354	///
355	/// Legacy format: no top-level `workflow:` key. The file is parsed as
356	/// `WorkflowConfig` and wrapped in a `WorkflowFile` with empty
357	/// `steps`/`vars`, preserving the workflow declaration as-is.
358	pub fn parse_workflow_file_value(
359	    value: serde_yaml::Value,
360	    source_path: &Path,
361	) -> Result<WorkflowFile> {
362	    let is_new_format = value
363	        .as_mapping()
364	        .map(|m| m.contains_key(serde_yaml::Value::String("workflow".to_string())))
365	        .unwrap_or(false);
366	
367	    if is_new_format {
368	        serde_yaml::from_value(value).map_err(|e| BivvyError::ConfigParseError {
369	            path: source_path.to_path_buf(),
370	            message: e.to_string(),
371	        })
372	    } else {
373	        let workflow: WorkflowConfig =
374	            serde_yaml::from_value(value).map_err(|e| BivvyError::ConfigParseError {
375	                path: source_path.to_path_buf(),
376	                message: e.to_string(),
377	            })?;
378	        Ok(WorkflowFile {
379	            description: workflow.description.clone(),
380	            steps: Default::default(),
381	            vars: Default::default(),
382	            workflow,
383	        })
384	    }
385	}
