886	    #[test]
887	    fn ensure_global_config_creates_config_and_schema() {
888	        let temp = TempDir::new().unwrap();
889	        let bivvy_dir = temp.path().join(".bivvy");
890	        let config_path = bivvy_dir.join("config.yml");
891	        let schema_path = bivvy_dir.join("schema.json");
892	
893	        assert!(!config_path.exists());
894	        assert!(!schema_path.exists());
895	
896	        ensure_global_config_in(temp.path().to_path_buf());
897	
898	        // config.yml created with expected content
899	        let written = fs::read_to_string(&config_path).unwrap();
900	        assert!(written.contains("# Bivvy global configuration"));
901	        assert!(written.contains("# settings:"));
902	        assert!(written.contains("#     output: verbose"));
903	        assert!(written.contains("#   parallel: false"));
904	        assert!(written.contains("#   auto_update: true"));
905	        assert!(written.contains("#   logging: false"));
906	
907	        // schema line points to the local schema.json
908	        assert!(written.contains(&format!(
909	            "# yaml-language-server: $schema={}",
910	            schema_path.display()
911	        )));
912	
913	        // File should be valid YAML (all comments, so it parses as empty/null)
914	        let parsed: serde_yaml::Value = serde_yaml::from_str(&written).unwrap();
915	        assert!(parsed.is_null());
916	
917	        // schema.json created and is valid JSON
918	        let schema_content = fs::read_to_string(&schema_path).unwrap();
919	        let schema: serde_json::Value = serde_json::from_str(&schema_content).unwrap();
920	        assert_eq!(schema["type"], "object");
921	    }
