554	/// Load and merge all config files for a project.
555	///
556	/// Discovers and merges configs in this order:
557	/// 1. Remote base configs (from `extends:`)
558	/// 2. User global config (`~/.bivvy/config.yml`)
559	/// 3. Project config (`.bivvy/config.yml`)
560	/// 4. Split-file steps (`.bivvy/steps/*.yml`)
561	/// 5. Split-file workflows (`.bivvy/workflows/*.yml`)
562	/// 6. Local overrides (`.bivvy/config.local.yml`)
563	///
564	/// # Errors
565	///
566	/// Returns `ConfigNotFound` if no project config exists.
567	/// Returns `ConfigParseError` if any config file is invalid.
568	pub fn load_merged_config(project_root: &Path) -> Result<BivvyConfig> {
569	    load_merged_config_with_resolver(project_root, &ExtendsResolver::default())
570	}
