572	/// Load and merge configs with a specific extends resolver.
573	///
574	/// This is the implementation behind `load_merged_config`, exposed
575	/// separately to allow injecting a custom resolver for testing.
576	pub fn load_merged_config_with_resolver(
577	    project_root: &Path,
578	    resolver: &ExtendsResolver,
579	) -> Result<BivvyConfig> {
580	    let paths = ConfigPaths::discover(project_root);
581	
582	    if !paths.has_project_config() {
583	        return Err(BivvyError::ConfigNotFound {
584	            path: project_root.join(".bivvy").join("config.yml"),
585	        });
586	    }
587	
588	    let configs = collect_config_values(&paths, WorkflowSelection::All)?;
589	
590	    // Merge all configs
591	    let merged = merge_configs(&configs);
592	
593	    // Parse merged value into typed config
594	    let config: BivvyConfig =
595	        serde_yaml::from_value(merged).map_err(|e| BivvyError::ConfigParseError {
596	            path: project_root.join(".bivvy").join("config.yml"),
597	            message: format!("Failed to parse merged config: {}", e),
598	        })?;
599	
600	    // Migrate deprecated fields (watches → change checks, etc.)
601	    let mut config = config;
602	    config.migrate_deprecated_fields();
603	
604	    // Resolve extends if present
605	    if config.extends.is_some() {
606	        let resolved = resolver.resolve(&config)?;
607	        Ok(resolved)
608	    } else {
609	        Ok(config)
610	    }
611	}
