        fs::write(
            bivvy_dir.join("config.yml"),
            format!("extends:\n  - url: {}\napp_name: MyApp\n", url),
        )
        .unwrap();

        // Pre-trust the URL
        let trust_dir = TempDir::new().unwrap();
        let trust_path = trust_dir.path().join("trusted_urls.yml");
        let mut store = TrustStore::default();
        store.trust(&url);
