        let result = parse_config("# just comments\n", Path::new("test.yml"));
        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
    }

    #[test]
    fn load_merged_config_errors_on_empty_project_config() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();
        fs::write(bivvy_dir.join("config.yml"), "").unwrap();

        let result = load_merged_config(temp.path());
        assert!(
            matches!(result, Err(BivvyError::ConfigParseError { .. })),
            "Empty project config should return a parse error, not silent defaults"
        );
    }

    #[test]
    fn empty_local_config_does_not_wipe_project_config() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();

        fs::write(
            bivvy_dir.join("config.yml"),
            r#"
app_name: MyApp
steps:
  build:
    command: "cargo build"
"#,
        )
        .unwrap();

        fs::write(bivvy_dir.join("config.local.yml"), "# empty overrides\n").unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        assert_eq!(
            config.app_name,
            Some("MyApp".to_string()),
            "Empty local config must not wipe the project config"
        );
        assert!(
            config.steps.contains_key("build"),
            "Steps from project config must survive an empty local override"
        );
    }
}

