2	//!
3	//! Two context sources:
4	//! 1. **Step context** — command, requires, template (already available)
5	//! 2. **Workflow state** — prior step results, what succeeded/failed/was skipped
6	
7	use crate::steps::StepStatus;
8	
9	use super::classify::ErrorCategory;
10	use super::{CategoryMatch, DiagnosticDetails, StepContext, WorkflowState};
11	
12	/// Refine category confidence and details using step + workflow context.
13	pub fn contextualize(
14	    categories: &mut [CategoryMatch],
15	    details: &mut DiagnosticDetails,
16	    step_ctx: &StepContext<'_>,
17	    workflow_state: &WorkflowState<'_>,
18	) {
19	    for cat in categories.iter_mut() {
20	        // Step context reinforcement
21	        apply_step_context_boost(cat, details, step_ctx);
22	
23	        // Workflow state heuristics
24	        apply_workflow_heuristics(cat, details, step_ctx, workflow_state);
25	
26	        // Clamp confidence to [0.0, 1.0]
27	        cat.confidence = cat.confidence.clamp(0.0, 1.0);
28	    }
29	
30	    // Re-sort by confidence after adjustments
31	    categories.sort_by(|a, b| {
32	        b.confidence
33	            .partial_cmp(&a.confidence)
34	            .unwrap_or(std::cmp::Ordering::Equal)
35	    });
36	
37	    // Extract service name from requires if we have a connection_refused
38	    if categories
39	        .iter()
40	        .any(|c| c.category == ErrorCategory::ConnectionRefused)
41	        && details.service.is_none()
42	    {
43	        for req in step_ctx.requires {
44	            if req.contains("postgres")
45	                || req.contains("redis")
46	                || req.contains("mysql")
47	                || req.contains("mongo")
48	                || req.contains("elasticsearch")
49	                || req.contains("rabbitmq")
50	                || req.contains("memcached")
51	            {
52	                details.service = Some(req.clone());
53	                break;
54	            }
55	        }
56	    }
57	}
58	
59	fn apply_step_context_boost(
60	    cat: &mut CategoryMatch,
61	    details: &DiagnosticDetails,
62	    step_ctx: &StepContext<'_>,
63	) {
64	    match cat.category {
65	        ErrorCategory::ConnectionRefused => {
66	            // Boost if step requires a service
67	            if step_ctx.requires.iter().any(|r| {
68	                r.contains("postgres")
69	                    || r.contains("redis")
70	                    || r.contains("mysql")
71	                    || r.contains("mongo")
